-- Bar Boschetto: catalogo NEVO 2025. Run in Supabase SQL Editor.
-- Idempotent. Existing non-null values (including zero), verified rows,
-- names and all account overrides are preserved. Missing values stay NULL.
begin;
create table if not exists public.bb_ingredients (
 ingredient_id text primary key,
 name_it text not null,
 name_nl text not null,
 kcal_100g numeric check(kcal_100g>=0),
 protein_g_100g numeric check(protein_g_100g>=0),
 carbs_g_100g numeric check(carbs_g_100g>=0),
 fat_g_100g numeric check(fat_g_100g>=0),
 manually_verified boolean not null default false,
 nutrient_sources jsonb not null default '{}'::jsonb,
 updated_at timestamptz not null default now()
);
alter table public.bb_ingredients enable row level security;
revoke all on public.bb_ingredients from public, anon, authenticated;
grant select on public.bb_ingredients to authenticated;
drop policy if exists bb_read_ingredients on public.bb_ingredients;
create policy bb_read_ingredients on public.bb_ingredients for select to authenticated using(true);
