insert into public.bb_ingredients(ingredient_id,name_it,name_nl,kcal_100g,protein_g_100g,carbs_g_100g,fat_g_100g,nutrient_sources)
select ingredient_id,name_it,name_nl,kcal_100g,protein_g_100g,carbs_g_100g,fat_g_100g,nutrient_sources from bb_nevo_seed
on conflict(ingredient_id) do update set
 kcal_100g=coalesce(bb_ingredients.kcal_100g,excluded.kcal_100g),
 protein_g_100g=coalesce(bb_ingredients.protein_g_100g,excluded.protein_g_100g),
 carbs_g_100g=coalesce(bb_ingredients.carbs_g_100g,excluded.carbs_g_100g),
 fat_g_100g=coalesce(bb_ingredients.fat_g_100g,excluded.fat_g_100g),
 nutrient_sources=bb_ingredients.nutrient_sources || case when bb_ingredients.kcal_100g is null and excluded.kcal_100g is not null then jsonb_build_object('kcal_100g',excluded.nutrient_sources->'kcal_100g') else '{}'::jsonb end || case when bb_ingredients.protein_g_100g is null and excluded.protein_g_100g is not null then jsonb_build_object('protein_g_100g',excluded.nutrient_sources->'protein_g_100g') else '{}'::jsonb end || case when bb_ingredients.carbs_g_100g is null and excluded.carbs_g_100g is not null then jsonb_build_object('carbs_g_100g',excluded.nutrient_sources->'carbs_g_100g') else '{}'::jsonb end || case when bb_ingredients.fat_g_100g is null and excluded.fat_g_100g is not null then jsonb_build_object('fat_g_100g',excluded.nutrient_sources->'fat_g_100g') else '{}'::jsonb end,
 updated_at=now()
where not bb_ingredients.manually_verified and ((bb_ingredients.kcal_100g is null and excluded.kcal_100g is not null) or (bb_ingredients.protein_g_100g is null and excluded.protein_g_100g is not null) or (bb_ingredients.carbs_g_100g is null and excluded.carbs_g_100g is not null) or (bb_ingredients.fat_g_100g is null and excluded.fat_g_100g is not null));

create or replace function public.bb_get_ingredients() returns jsonb
language sql stable security invoker set search_path='' as $$
 select coalesce(jsonb_agg(to_jsonb(i) order by i.ingredient_id),'[]'::jsonb)
 from public.bb_ingredients i;
$$;
revoke all on function public.bb_get_ingredients() from public,anon;
grant execute on function public.bb_get_ingredients() to authenticated;
commit;
-- Expected on a new catalog: 190 total, 129 complete, 61 without values.
select count(*) as total,
 count(*) filter(where kcal_100g is not null and protein_g_100g is not null and carbs_g_100g is not null and fat_g_100g is not null) as complete,
 count(*) filter(where kcal_100g is null and protein_g_100g is null and carbs_g_100g is null and fat_g_100g is null) as without_values
from public.bb_ingredients;
